for name, method, raw, state in (
        ("layer-name", "getName", '"Layer 1"', {"name": "Layer 1"}),
        ("layer-blend-mode", "getBlendMode", '"Add"', {"blend_mode": "Add"}),
        ("layer-opacity", "getOpacity", "0.75", {"opacity": 0.75}),
        ("layer-volume", "getVolume", "1.0", {"volume": 1.0}),
        ("layer-speed", "getPlaybackSpeed", "-1.0", {"speed": -1.0}),
        ("layer-transport", "getTransportMode", "2", {"transport": "pause"}),
        ("layer-muted", "getIsLayerMuted", "true", {"muted": True}),
        ("layer-audio-muted", "getIsAudioMuted", "false", {"audio_muted": False})):
    telemetry(PX, name, request=_req("Pixera.Timelines.Layer." + method, '"handle":7001'),
              inbound=_reply(raw), expect_state={"layers": {"7001": state}})
# The same reply to another layer method sets nothing.
